use vstd::prelude::*;

verus! {
    /// Returns the maximum element of a non‐empty array of i8's,
    /// witnessed by its first occurrence.
    fn amax(a: Vec<i8>) -> (result: i8)
        requires
            // The array must be non‐empty.
            a.len() > 0,
        ensures
            // Every element of the array is ≤ result.
            forall |j: nat| j < a.len() ==> a@j <= result,
        ensures
            // There is some index i0 < len(a) such that a[i0] == result,
            // and for all j < i0, a[j] < result.
            exists |i0: nat|
                i0 < a.len()
             && a@i0 == result
             && (forall |j: nat| j < i0 ==> a@j < result)
    {
        // Initialize max with the first element; that's the first occurrence.
        let mut max: i8 = a[0];
        let mut idx: usize = 1;
        let len = a.len();
        // Scan the rest of the array.
        while idx < len
            invariant
                idx <= len,
                // All seen elements so far are ≤ max.
                forall |j: nat| j < idx ==> a@j <= max,
                // max really occurs in [0 .. idx), and it's the first occurrence.
                exists |i0: nat|
                    i0 < idx
                 && a@i0 == max
                 && (forall |j: nat| j < i0 ==> a@j < max),
            decreases
                len - idx,
        {
            let ai = a[idx];
            if ai > max {
                // We have found a strictly bigger value;
                // its index idx is now the first occurrence of the new max.
                max = ai;
            }
            idx += 1;
        }
        max
    }
}

